#include "../source/NativeSfizzInstrument.h"
#include <cmath>
int main(){juce::ScopedJuceInitialiser_GUI init;for(bool bass:{false,true}){NativeSfizzInstrument p(bass);p.prepareToPlay(48000,512);juce::AudioBuffer<float> b(2,512);juce::MidiBuffer m;m.addEvent(juce::MidiMessage::noteOn(1,60,(juce::uint8)100),128);p.processBlock(b,m);float pre=b.getMagnitude(0,0,128),post=b.getMagnitude(0,128,384);if(pre!=0||post<1e-7f)return bass?2:1;p.getParameters()[0]->setValueNotifyingHost(0.32f);juce::MemoryBlock state;p.getStateInformation(state);NativeSfizzInstrument restored(bass);restored.setStateInformation(state.getData(),(int)state.getSize());if(std::abs(restored.getParameters()[0]->getValue()-0.32f)>0.01f)return 5;restored.prepareToPlay(48000,512);juce::MidiBuffer m2;m2.addEvent(juce::MidiMessage::noteOn(1,60,(juce::uint8)100),0);restored.processBlock(b,m2);if(b.getMagnitude(0,0,512)<1e-7f)return bass?4:3;}return 0;}
